    ScriptEntry Script_None
    ScriptEntry GR_Glacia  // 2: EverGrandeCity_GlaciasRoom_EventScript_Glacia  // story:
    ScriptEntry GR_Init  // 3: zone init (EverGrandeCity_GlaciasRoom_OnLoad: the doors)  // story:
