// ---- story (chapter Ch11, ch11 agent 2026-10-07; Sapphire data/maps/EverGrandeCity_GlaciasRoom/scripts.inc and data/scripts/elite_four.inc;
// generators must keep everything from this line on; entries above marked "// story:")
// Scripts 2-4, text lines 1-2 (line 0 is the generator's). Room tiles = Sapphire tiles + (1,-1). Glacia (uid 1, (6,5), model 96)
// is placed by data/story/ch11.json.
// The doors (Sapphire: setmetatile): the room's two warps are the doors, the entrance (warp 0, Sapphire (6,13)) and the exit
// (warp 1, Sapphire (6,2), room tile (7,1)). The exit's warp is moved off the map (ObjInitWarpGPos) until Glacia is beaten, the
// entrance's once you have walked in (VAR_ELITE_4_STATE 3) or beaten Glacia. The door models stay as the room builder made them.
// playbgm MUS_ENCOUNTER_ELITE_FOUR: with the Hoenn music answer only (h_playbgm_hoenn; Unova: the room's music goes on).
// Not ported: the spotlight metatiles that go dark (the room has none).
#define T_IntroSpeech 1
#define T_PostBattleSpeech 2
#define GR_ENTRY_WARP 0
#define GR_EXIT_WARP 1

GR_Glacia:                                   // EverGrandeCity_GlaciasRoom_EventScript_Glacia
    ActorsPauseAll
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    h_goto_if_set FLAG_DEFEATED_ELITE_4_GLACIA, L_GR_PostBattle
    h_playbgm_hoenn MUS_HOENN_ENCOUNTER_ELITE_FOUR    // Sapphire: playbgm MUS_ENCOUNTER_ELITE_FOUR
    h_msgbox T_IntroSpeech                     // intro (the in-battle defeat line is the trainer's message 1)
    h_closemessage
    h_setflag FLAG_E4_BATTLE_PENDING           // (cleared when won; still set after a whiteout: the League lobby resets the Elite Four)
    h_trainerbattle TRAINER_GLACIA
    h_clearflag FLAG_E4_BATTLE_PENDING
    h_setflag FLAG_DEFEATED_ELITE_4_GLACIA
    VMCall GR_SetAdvanceToNextRoom
    h_msgbox T_PostBattleSpeech
    h_release
L_GR_PostBattle:                            // ..._EventScript_PostBattleSpeech
    h_msgbox T_PostBattleSpeech
    h_release

GR_SetAdvanceToNextRoom:                    // PokemonLeague_EliteFour_SetAdvanceToNextRoomMetatiles
    h_applymovement 255, Common_Movement_Delay32
    h_waitmovement
    SEPlay SEQ_SE_KAIDAN                       // SE_DOOR (stand-in)
    ObjInitWarpGPos GR_EXIT_WARP, 7, 0, 1   // the exit door opens: warp 1 back at Sapphire (6,2) = room tile (7,1)
    VMReturn

GR_WalkIn:                                  // ..._EventScript_WalkInCloseDoor (PokemonLeague_EliteFour_EventScript_WalkInCloseDoor)
    ActorsPauseAll
    h_applymovement 255, Common_Movement_WalkUp6
    h_waitmovement
    SEPlay SEQ_SE_KAIDAN                       // SE_TRUCK_DOOR (stand-in)
    ObjInitWarpGPos GR_ENTRY_WARP, 0, 0, 0  // the entrance closes behind you
    h_setvar VAR_ELITE_4_STATE, 3
    h_release

GR_Init:                                    // ..._OnLoad (the zone init)
#ifdef HOENN_TEST_CH11
    VMCall Test_Ch11Start                      // test builds only (scenes/ch11_test.inc)
#endif
    h_goto_if_set FLAG_DEFEATED_ELITE_4_GLACIA, L_GR_Defeated     // ResetAdvanceToNextRoom: the exit open, the entrance closed
    ObjInitWarpGPos GR_EXIT_WARP, 0, 0, 0   // the exit door is shut
    h_goto_if_ne VAR_ELITE_4_STATE, 3, L_GR_InitDone
    ObjInitWarpGPos GR_ENTRY_WARP, 0, 0, 0  // CloseDoor
L_GR_InitDone:
    VMHalt
L_GR_Defeated:
    ObjInitWarpGPos GR_ENTRY_WARP, 0, 0, 0
    VMHalt

    .balign 4, 0
